  ('5eed0002-0000-4000-8000-000000000003', 'klinika-sunce', 'Klinika Sunce', 'Zdravstvena ustanova Klinika Sunce Čačak',
   'Privatna klinika opšte medicine i pedijatrije.', 'https://klinika-sunce.example', 'Čačak', '[]'),
  ('5eed0002-0000-4000-8000-000000000004', 'datalab', 'DataLab Analitika', 'DataLab Analitika d.o.o. Novi Sad',
   'Tim data naučnika i inženjera koji firmama pomaže da iz sopstvenih podataka donose odluke. Radimo prognoze prodaje, obradu teksta na srpskom jeziku i izveštaje u Power BI-ju.', 'https://datalab.example', 'Novi Sad',
   '[{"type":"email","value":"kontakt@datalab.example"}]'),
  ('5eed0002-0000-4000-8000-000000000005', 'oblak-sistemi', 'Oblak Sistemi', 'Oblak Sistemi d.o.o. Beograd',
   'Održavamo servere, mreže i oblak infrastrukturu za više od stotinu firmi u Srbiji. Dežurni tim je dostupan dvadeset četiri sata dnevno.', 'https://oblak-sistemi.example', 'Beograd',
   '[{"type":"phone","value":"+381 11 555 0190","description":"dežurni tim"},{"type":"email","value":"podrska@oblak-sistemi.example"}]'),
  ('5eed0002-0000-4000-8000-000000000006', 'hotel-panorama', 'Hotel Panorama Zlatibor', 'Panorama turizam d.o.o. Čajetina',
   'Hotel sa četiri zvezdice, spa centrom i restoranom domaće kuhinje, na pet minuta hoda od centra Zlatibora.', 'https://hotel-panorama.example', 'Zlatibor',
   '[{"type":"phone","value":"+381 31 555 0120","description":"recepcija"},{"type":"instagram","value":"https://www.instagram.com/hotel.panorama.demo"}]'),
  ('5eed0002-0000-4000-8000-000000000007', 'pekara-zrno', 'Pekara Zrno', 'Zrno pekarstvo d.o.o. Kragujevac',
   'Porodična pekara sa šest radnji u Kragujevcu. Hleb mesimo od domaćeg brašna, bez aditiva, svako jutro od četiri sata.', NULL, 'Kragujevac',
   '[{"type":"phone","value":"+381 34 555 0133"},{"type":"facebook","value":"https://www.facebook.com/pekara.zrno.demo"}]'),
  ('5eed0002-0000-4000-8000-000000000008', 'ekspres-logistika', 'Ekspres Logistika', 'Ekspres Logistika d.o.o. Šabac',
   'Drumski prevoz robe po Srbiji i Evropi i magacin od osam hiljada kvadrata pored auto-puta.', 'https://ekspres-logistika.example', 'Šabac',
   '[{"type":"email","value":"posao@ekspres-logistika.example","description":"zapošljavanje"},{"type":"phone","value":"+381 15 555 0170"}]'),
  ('5eed0002-0000-4000-8000-000000000009', 'gradnja-plus', 'Gradnja Plus', 'Gradnja Plus d.o.o. Niš',
   'Gradimo stambene zgrade i poslovne objekte na jugu Srbije. Trenutno imamo tri aktivna gradilišta u Nišu.', 'https://gradnja-plus.example', 'Niš',
   '[{"type":"phone","value":"+381 18 555 0155"}]'),
  ('5eed0002-0000-4000-8000-000000000010', 'lingva', 'Škola jezika Lingva', 'Andrea Horvat PR Škola jezika Lingva Subotica',
   'Kursevi engleskog, nemačkog i mađarskog jezika za decu i odrasle, pripreme za međunarodne ispite i prevodi.', 'https://lingva.example', 'Subotica',
