  ('5eed0002-0000-4000-8000-000000000011', 'bilans-plus', 'Bilans plus', 'Bilans plus d.o.o. Beograd',
   'Knjigovodstvo, obračun zarada i poresko savetovanje za preduzetnike i mala preduzeća.', 'https://bilans-plus.example', 'Beograd',
   '[{"type":"email","value":"kancelarija@bilans-plus.example"}]'),
  ('5eed0002-0000-4000-8000-000000000012', 'studio-kadar', 'Studio Kadar', 'Studio Kadar d.o.o. Beograd',
   'Produkcija reklama, muzičkih spotova i dokumentarnih filmova. Vodimo i društvene mreže za dvadesetak brendova.', 'https://studio-kadar.example', 'Beograd',
