-- Posts, comments and reactions

INSERT INTO post (id, content, created_by_id, created_for_id, created_at) VALUES
  ('5eed0003-0000-4000-8000-000000000001', 'Kodnest zapošljava! Tražimo Java programera, UX dizajnera i studente za praksu. Detalji su u oglasima na našem profilu.',
   '5eed0001-0000-4000-8000-000000000001', '5eed0002-0000-4000-8000-000000000001', now() - interval '6 days'),
  ('5eed0003-0000-4000-8000-000000000002', 'Posle tri godine rada sa Spring Boot-om, najveća lekcija: testovi nad pravom bazom otkrivaju greške koje mock nikad ne pokaže.',
   '5eed0001-0000-4000-8000-000000000001', '5eed0001-0000-4000-8000-000000000001', now() - interval '5 days'),
  ('5eed0003-0000-4000-8000-000000000003', 'Počinje sezona berbe malina. Ove godine očekujemo rekordan rod i tražimo sezonske radnike iz okoline Novog Sada.',
   '5eed0001-0000-4000-8000-000000000002', '5eed0002-0000-4000-8000-000000000002', now() - interval '4 days 20 hours'),
  ('5eed0003-0000-4000-8000-000000000004', 'Završio sam redizajn aplikacije za lokalnu biblioteku. Najviše vremena otišlo je na pristupačnost i kontrast boja.',
   '5eed0001-0000-4000-8000-000000000004', '5eed0001-0000-4000-8000-000000000004', now() - interval '4 days'),
  ('5eed0003-0000-4000-8000-000000000005', 'Naš tim je ovog vikenda bio na hakatonu u Novom Sadu i osvojio drugo mesto. Hvala svima koji su navijali!',
   '5eed0001-0000-4000-8000-000000000005', '5eed0002-0000-4000-8000-000000000001', now() - interval '3 days'),
  ('5eed0003-0000-4000-8000-000000000006', 'Klinika Sunce otvara novu ambulantu za decu. Tražimo medicinske sestre i tehničare sa iskustvom u pedijatriji.',
   '5eed0001-0000-4000-8000-000000000007', '5eed0002-0000-4000-8000-000000000003', now() - interval '2 days 6 hours'),
  ('5eed0003-0000-4000-8000-000000000007', 'Student sam završne godine elektrotehnike i tražim praksu u oblasti razvoja softvera. Svaki savet je dobrodošao.',
   '5eed0001-0000-4000-8000-000000000006', '5eed0001-0000-4000-8000-000000000006', now() - interval '1 day 20 hours'),
  ('5eed0003-0000-4000-8000-000000000008', 'Savet za CV: prvo navedite rezultate, pa tek onda odgovornosti. Regruter vaš CV pregleda za manje od minuta.',
   '5eed0001-0000-4000-8000-000000000003', '5eed0001-0000-4000-8000-000000000003', now() - interval '1 day'),
  ('5eed0003-0000-4000-8000-000000000009', 'Prvi dan na Sponi. Pozdrav svima!',
   '5eed0001-0000-4000-8000-000000000008', '5eed0001-0000-4000-8000-000000000008', now() - interval '10 hours'),
  ('5eed0003-0000-4000-8000-000000000010', 'Da li neko ima iskustva sa hibridnim radom u poljoprivredi? Deo posla je na terenu, a deo u kancelariji.',
   '5eed0001-0000-4000-8000-000000000002', '5eed0001-0000-4000-8000-000000000002', now() - interval '3 hours'),
  ('5eed0003-0000-4000-8000-000000000011', 'Kodnest je od danas i na Sponi! Ovde ćemo objavljivati vesti iz tima, oglase za posao i poneki tekst o tome kako radimo.',
   '5eed0001-0000-4000-8000-000000000001', '5eed0002-0000-4000-8000-000000000001', now() - interval '55 days'),
  ('5eed0003-0000-4000-8000-000000000012', 'Ove nedelje smo ugostili dvadeset studenata Elektrotehničkog fakulteta na danu otvorenih vrata. Zajedno smo prošli kroz ceo jedan sprint, od planiranja do demo prezentacije. Hvala svima na sjajnim pitanjima!',
   '5eed0001-0000-4000-8000-000000000005', '5eed0002-0000-4000-8000-000000000001', now() - interval '27 days'),
  ('5eed0003-0000-4000-8000-000000000013', E'Kako pišemo korisničke priče u Kodnestu?\n\nJedna priča, jedan korisnik, jedan cilj. Ako priču ne možete da testirate, niste je ni završili.\n\nSvaka priča ima kriterijume prihvatanja koje razume i neko ko nije programer. Ako ih klijent ne može da pročita i da kaže da je baš to tražio, vraćamo ih na doradu.\n\nNajveća promena koju smo uveli prošle godine: priču procenjuje ceo tim zajedno, a ne samo onaj ko će je raditi. Procene su od tada tačnije, a iznenađenja na kraju sprinta ređa.',
   '5eed0001-0000-4000-8000-000000000019', '5eed0002-0000-4000-8000-000000000001', now() - interval '24 days'),
  ('5eed0003-0000-4000-8000-000000000014', 'Počeli smo rad na aplikaciji za zakazivanje pregleda u domovima zdravlja. Prva verzija ide na testiranje za mesec dana, a mi već brojimo dane.',
   '5eed0001-0000-4000-8000-000000000005', '5eed0002-0000-4000-8000-000000000001', now() - interval '15 days'),
  ('5eed0003-0000-4000-8000-000000000015', 'Kodnest od januara otvara kancelariju u Novom Sadu! Ako ste iz Novog Sada i volite Javu, pogledajte oglas za junior programera na našem profilu.',
   '5eed0001-0000-4000-8000-000000000002', '5eed0002-0000-4000-8000-000000000001', now() - interval '9 days'),
  ('5eed0003-0000-4000-8000-000000000016', 'Tražimo product menadžera za naš proizvod za privatne klinike. Ako umete da razgovarate i sa lekarima i sa programerima, oglas je na našem profilu.',
   '5eed0001-0000-4000-8000-000000000019', '5eed0002-0000-4000-8000-000000000001', now() - interval '2 days'),
  ('5eed0003-0000-4000-8000-000000000017', E'Pre pet godina napisala sam prvi red koda za Kodnest, za kuhinjskim stolom kod roditelja. Prvi klijent bila je teretana iz komšiluka, a prva faktura kasnila je tri meseca.\n\nDanas nas je osamnaest i selimo se u veću kancelariju. Hvala svima koji su verovali u nas od prvog dana.',
   '5eed0001-0000-4000-8000-000000000001', '5eed0001-0000-4000-8000-000000000001', now() - interval '72 days'),
  ('5eed0003-0000-4000-8000-000000000018', 'Pitanje za programere: koliko vremena dnevno provodite na pregledu tuđeg koda? Kod nas je to skoro sat po osobi i ne bih menjala ništa.',
   '5eed0001-0000-4000-8000-000000000001', '5eed0001-0000-4000-8000-000000000001', now() - interval '34 days'),
  ('5eed0003-0000-4000-8000-000000000019', 'Sa konferencije u Beogradu: najbolje predavanje dana bilo je o pristupačnosti. Od deset sajtova koje su testirali, samo jedan može da se koristi bez miša. Više o tome sutra.',
   '5eed0001-0000-4000-8000-000000000001', '5eed0001-0000-4000-8000-000000000001', now() - interval '13 hours'),
  ('5eed0003-0000-4000-8000-000000000020', 'Tri godine vodim Zelenu baštu i isto toliko pomažem Kodnestu. Ljudi me pitaju kako to spajam. Odgovor je jednostavan: i u poljoprivredi i u softveru pobeđuje onaj ko dobro planira.',
   '5eed0001-0000-4000-8000-000000000002', '5eed0001-0000-4000-8000-000000000002', now() - interval '38 days'),
  ('5eed0003-0000-4000-8000-000000000021', 'Zelena bašta je sada na Sponi. Pratite nas za vesti sa polja i oglase za sezonske poslove.',
   '5eed0001-0000-4000-8000-000000000002', '5eed0002-0000-4000-8000-000000000002', now() - interval '43 days'),
  ('5eed0003-0000-4000-8000-000000000022', 'Završili smo redizajn ambalaže za naše maline. Nova kutija je od recikliranog kartona, a na poklopcu je ilustracija našeg voćnjaka.',
   '5eed0001-0000-4000-8000-000000000004', '5eed0002-0000-4000-8000-000000000002', now() - interval '18 days'),
  ('5eed0003-0000-4000-8000-000000000023', 'Završena je prva berba jagoda iz plastenika. Hvala svim beračima koji su bili uz nas od šest ujutru!',
   '5eed0001-0000-4000-8000-000000000002', '5eed0002-0000-4000-8000-000000000002', now() - interval '7 days'),
  ('5eed0003-0000-4000-8000-000000000024', 'Klinika Sunce je od danas na Sponi. Ovde ćete naći naše oglase za posao i vesti o novim ambulantama.',
   '5eed0001-0000-4000-8000-000000000007', '5eed0002-0000-4000-8000-000000000003', now() - interval '33 days'),
  ('5eed0003-0000-4000-8000-000000000025', 'Od ponedeljka radimo i subotom, od osam do četrnaest časova. Preglede zakazujete telefonom ili lično na recepciji.',
   '5eed0001-0000-4000-8000-000000000023', '5eed0002-0000-4000-8000-000000000003', now() - interval '16 days'),
  ('5eed0003-0000-4000-8000-000000000026', 'Podsećamo roditelje da je u toku jesenja vakcinacija. Ponesite zdravstvenu knjižicu deteta i karton vakcinacije.',
   '5eed0001-0000-4000-8000-000000000023', '5eed0002-0000-4000-8000-000000000003', now() - interval '5 days'),
  ('5eed0003-0000-4000-8000-000000000027', 'Posle deset godina rada u domu zdravlja, najvažnije što sam naučila o pedijatriji: roditelja treba saslušati do kraja. On svoje dete poznaje bolje od bilo koje analize.',
   '5eed0001-0000-4000-8000-000000000007', '5eed0001-0000-4000-8000-000000000007', now() - interval '28 days'),
  ('5eed0003-0000-4000-8000-000000000028', 'Najčešća greška na razgovoru za posao? Kandidat ne postavi nijedno pitanje. Pitajte kako izgleda prvi mesec, ko će vam biti mentor i kako se meri uspeh. To pokazuje da vas posao zaista zanima.',
